operations.style:
min-width: 0px; padding: 24px; border-radius: 16px; background-color: #152735; display: flex; flex-direction: column; gap: 12px; grid-column: 1; grid-row: 1;
@media(--mobile) { padding: 16px; gap: 10px; grid-column: 1; grid-row: 2; }
& > .elementor-widget:has(.woocommerce-Price-amount) { text-align: left; }
& .woocommerce-Price-amount { color: #46D7A6; }
& .woocommerce-Price-amount bdi { display: inline-flex; flex-direction: row-reverse; align-items: baseline; gap: .35em; direction: ltr; }
